Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Labo bakhona endleleni eqondile evela eNkosini yabo, futhi labo-ke ngabaphumeleli. 2:5; 31:5
- = Nina Bantwana bakwa-Israyeli! Khumbulani umusa Wami engawunika wena nokuthi nginikhethile ngaphezu kwemihlaba (izizwe) yonke. 2:47; 2:122
- = Lelo kwakuyisizwe esadlula. Esalo yilo elakuzuza, futhi esenu yilo enikuzuza. Futhi aniyukubuzwa ngalokho ababekwenza. 2:134; 2:141
- = Bahlala khona phakade; isijeziso asiyukuncishiswa kubo, futhi abayukuthola ithuba. 2:162; 3:88
- = Ngaphandle kwalabo abaphenduka ngemva kwalokho futhi bazilungisa. Ngempela, uAllah ungumxoleli, unesihawu. 3:89; 24:5
- = Kodwa labo abangakholwa futhi baphika izimpawu zethu – labo-ke bangabangane besihogo. 5:10; 5:86
- = Futhi asikho isibonakaliso esiza kubo eziphawulweni zeNkosi yabo, ngaphandle kokuthi basifulathele. 6:4; 36:46
- = Futhi ngempela izithunywa zahlekwa ngaphambi kwakho, kodwa labo ababekade behleka bazungezwa yilokho ababekade bekuhleka. 6:10; 21:41
- = Yithi: "Ngempela mina ngiyesaba, uma ngingamlaleli uMbuso wami, isijeziso soSuku olukhulu." 6:15; 39:13
- = Ngakho-ke ukuzamazama komhlaba kwabathatha, baba sezindlini zabo begingqikile. 7:78; 7:91
- = Ngakho-ke waphonsa induku yakhe, kwathi kungoko, yaba inyoka esobala. 7:107; 26:32
- = Futhi wakhipha isandla sakhe, kwathi kungoko, sabamhlophe (sikhazimulayo) kulabo ababebukela. 7:108; 26:33
- = Bathi: "Sikholwa eNkosini yemihlaba." 7:121; 26:47
- = INkosi kaMose no-Aroni. 7:122; 26:48
- = Futhi ngizobanika ithuba. Ngempela, icebo lami liqinile. 7:183; 68:45
- = Yena nguyena owathumela iSithunywa sakhe ngesiqondiso kanye nenkolo yeqiniso, ukuze ayiphakamise ngaphezu kwazo zonke izinkolo, nakuba abahlanganyeli bezonda. 9:33; 61:9
- = Hhayi Mphrofethi! Yilwa nabangakholwa kanye nabazenzisi, futhi ube nzima kubo. Indawo yabo eyisipele isihogo, futhi kubi kakhulu lapho kubuyiselwa khona! 9:73; 66:9
- = Futhi bathi: "Lesisithembiso siyofika nini, uma nina kungabe niyiqiniso?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Futhi ngempela sathumela uMose ngezimpawu zethu kanye negunya elicacile. 11:96; 40:23
- = Futhi ngempela sanika uMose iNcwadi, kodwa kwaba nokuphikisana ngayo. Futhi ukuba bekungeyona ilizwi elandulelayo elivela eNkosini yakho, bekungayokwehlulelwa phakathi kwabo. Futhi ngempela bona, ngayo, bangabazayo. 11:110; 41:45
- = Lokho akunzima kuAllah. 14:20; 35:17
- = "Futhi uma sengimubumbile ngaphakathi futhi ngiphefumulela kuwo umoya wami, ngakho-ke yiwani phansi ngokukhothamela kuye." 15:29; 38:72
- = Ngakho-ke izingelosi zakhothama – zonke ngazinye. 15:30; 38:73
- = (UAllah) wathi: "Phuma ke kuyo, ngoba ngempela wena ungumxoshwa." 15:34; 38:77
- = (u-Iblis) wathi: "Nkosi yami! Ngakho-ke nginike ithuba kuze kube usuku abayovuswa ngalo." 15:36; 38:79
- = (UAllah) wathi: "Ngakho-ke ngempela wena ungomunye walabo abanikwa ithuba." 15:37; 38:80
- = Kuze kube usuku lwesikhathi esaziwayo." 15:38; 38:81
- = Ngaphandle kwezinceku zakho ezikhethiwe phakathi kwabo. 15:40; 38:83
- = Ngempela, abamesabayo uAllah bayokuba sezingadini nasemithonjeni. 15:45; 51:15
- = (u-Abrahamu) wathi: "Ngakho-ke yini inhloso yenu, nina zithunywa?" 15:57; 51:31
- = Bathi: "Ngempela, sithunywe kubantu abayizoni." 15:58; 51:32
- = Labo abakholwayo futhi bengaxubanga ukholo lwabo nokungabi nabulungisa – labo-ke banokuphepha, futhi bona bangabaholekayo. 16:42; 29:59
- = Ukuze bengabongi ngalokho esibanike kona. Ngakho-ke jabulelani, ngoba nizokwazi. 16:55; 30:34
- = Ngemva kwalokho walandela indlela. 18:89; 18:92
- = Hamba uye kuFaro. Ngempela, yena weqa umngcele. 20:24; 79:17
- = Futhi labo abagcina izitho zangasese zabo. 23:5; 70:29
- = Ngaphandle kwabafazi babo noma labo abaphethwe yizingalo zabo zesokunene – ngoba ngempela bona abasolwa. 23:6; 70:30
- = Kodwa lowo ofuna ngaphezu kwalokho, labo-ke bangabagabadeleli bomthetho. 23:7; 70:31
- = Futhi labo abagcina izibopho zabo kanye nezivumelwano zabo. 23:8; 70:32
- = (uNowa) wathi: "Nkosi yami! Ngisize, ngoba bayangiphika." 23:26; 23:39
- = Ta, Sin, Mim. 26:1; 28:1
- = Lezi yizingqephu zeNcwadi ecacile. 26:2; 28:2
- = Ngempela kulokho kunophawu, kodwa iningi labo abakholwanga. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = Futhi ngempela, iNkosi yakho – Yona inguSomandla, unesihawu. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = Futhi saminzisa abanye. 26:66; 37:82
- = Ngempela, mina ngiyisithunywa esithembekile kini. 26:107; 26:125; 26:143; 26:162; 26:178
- = Ngakho-ke yesabani uAllah futhi ngilaleleni. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
