- Emhlabeni futhi babheke ukuthi isiphetho salabo abangaphambili sasinjani. (فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ) 30:9; 30:42; 35:44; 40:82; 47:10
- Ngubani ongcolile ngaphezu kwalowo oqamba amanga ngo-Allah noma (ophika)? (وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ) 6:21; 6:93; 7:37; 10:17; 29:68
- Futhi uma enquma into, uthi kuyo kuphela: "Yiba!" futhi iyaba. (وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 2:117; 3:47; 19:35; 40:68
- Futhi aninaye umvikeli noma umsizi ngaphandle kuka-Allah. (وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 9:116; 29:22; 42:31
- Ngempela, ngizobasula izono zabo futhi ngibangenise ezingadini eziwela imifula ngaphansi kwazo. (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- Sizobangenisa ezingadini eziwela imifula ngaphansi kwazo, bahlale khona phakade. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- INkosi yakho iyona eyazi kakhulu ukuthi ubani oduka endleleni yayo, futhi iyona eyazi kakhulu. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- Niyobuyiselwa koWazi okungabonakali nokubonakalayo, bese enitshela ngalokhu enikwenzile. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- Babulala amadodana enu, bashiya abesifazane benu bephila; futhi kulokho kunesivivinyo esikhulu esivela eNkosini yenu. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- Ngempela, iNkosi yakho iyona eyazi kakhulu ukuthi ubani oduka endleleni yayo, futhi yona. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- U-Allah, ongokwakhe okusezulwini nokusemhlabeni. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- Ezizweni ezingaphambi kwenu – phakathi kwama-jinn nabantu. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- Khonzelani u-Allah; aninaye omunye unkulunkulu ngaphandle kwakhe. Animesabi yini? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- Futhi sibeke izembozo ezinhliziyweni zabo ukuze bangakuqondi, nasezindlebeni zabo ubunzima. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- Uyahlulela phakathi kwabo ngosuku lokuvuka mayelana nalokho ababephikisana ngakho. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- Wathi: "Oh bantu bami! Ngabe niyabona uma ngisobufakazi obusobala obuvela eNkosini yami?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- Lokho kungenxa yalokhu izandla zenu ezikuthumele kuqala, nokuthi u-Allah akangabikho ngcwele. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- Kulo mhlaba kunehlazo, futhi ngemuva kukho isijeziso esikhulu. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- Okusezulwini nokusemhlabeni; futhi u-Allah wanele njengoMvikeli. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- Ngaphandle kwalabo abakholwayo futhi benza imisebenzi emihle; bona banomvuzo ongapheli. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- Ukuze ungihlanganise ngento ongenalwazi ngayo; ngakho-ke ungabalaleli. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- Ngempela, lesi yisikhumbuzi; ngakho-ke lowo othandayo, makathathe indlela eya eNkosini yakhe. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- Futhi lowo obongayo, ubonga ngenxa yomphefumulo wakhe; futhi lowo ongabongi, ngempela. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- Labo abamisa umkhuleko, futhi banikele ngezaka, futhi bona banesiqiniseko ngempilo ezayo. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- (Ku) Ibrahim, Isma'il, Ishaq, Ya'qub, kanye namazwe; nokunikezwa uMusa no-Isa. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- Ngamaqembu, kuze kufike lapho befika khona, izicabha zayo ziyavulwa, futhi abaqaphi bayo bathi kubo. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- U-Allah akayibambi ngamazwi angenamgomo ezifungweni zenu, kodwa uyabamba ngento eniyo. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- Umusa, bayawujabulela; kodwa uma ububi buwafika ngento izandla zabo ezikuthumele kuqala. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- Eziwela imifula ngaphansi kwazo, bahlala khona phakade; futhi umvuzo omuhle kangakanani wabasebenzi! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- U-Allah uyakwazi okusezulwini nokusemhlabeni; futhi u-Allah. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- Lalelani u-Allah, futhi lalelani uMthunywa; kodwa uma niphenduka, kuye kuphela. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- Umvuzo wabo unyeNkosini yabo; akukho ukwesaba phezu kwabo, futhi bona. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- Futhi bathi: "Uma sesingamathambo nothuli, ngempela siyovuswa kabusha njengendalo entsha?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- Futhi abayitholi kubo umvikeli noma umsizi ngaphandle kuka-Allah. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- Wahlala isikhathi esingakanani? Wathi: "Ngahlala usuku noma ingxenye yosuku." Wathi: (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- Phakade kuze kube usuku lokuvuka. Ngubani ongunkulunkulu ngaphandle kuka-Allah ongakuletha (lokhu)? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- Lowo owenza okulungileyo – owesilisa noma owesifazane – futhi engokholwa. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- Labo abavimba endleleni ka-Allah futhi bayifuna igobile, futhi bengakholelwa empilweni ezayo. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- Noma kuphi lapho nithanda khona, futhi ningasondeli kulesi sihlahla, hlezi nibe ngabangcolile. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- Yithi: "Oh bantu bami! Yenzani ngokwesimo senu; mina ngiyasebenza; nizokwazi." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- Ngempela, abalahlekileyo yilabo abalahlekelwa imiphefumulo yabo nemindeni yabo ngosuku lokuvuka. Qaphelani! (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- Lowo oholwayo, uholwa ngenxa yomphefumulo wakhe; futhi lowo odukayo, uduka ngenxa yakhe; futhi akekho. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- Futhi abangakholwayo bathi: "Kungani kungathunyelwanga kuye isibonakaliso esivela eNkosini yakhe?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- Lowo owenza ubusuku ukuze niphumule kubo, nemini ukuze nibone. Ngempela. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- Ngaphambi kokuba kufike usuku olungenakuthengiswa noma (ubungane) kulo. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- Ukuze bacabangisise; umngane wabo akahlanyi; akayilutho ngaphandle komxwayisi. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- Bahlala khona phakade; isijeziso asiyukuncishiswa kubo, futhi abayukunikezwa ithuba. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- Ungathwasi amehlo akho kulokhu esibanike kona ukuze bakujabulele. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- Futhi ninganciphisi abantu ezintweni zabo, futhi ningenzeli ukonakaliswa emhlabeni. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- Futhi ukuthula kube phezu kwakhe ngosuku azalwa ngalo, nosuku ayofela ngalo, nosuku ayovuswa ngalo. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- Oh bantu bami! Yenzani ngokwesimo senu; mina ngiyasebenza; nizokwazi ukuthi ngubani. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- Futhi akufanelekile ukuthi uMthunywa eze nesibonakaliso ngaphandle kwemvume ka-Allah. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- Ngemuva kwalokho wonke umphefumulo uyoholelwa ngokugcwele lokho okwenzile, futhi abayukwenziwa okungcolile. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- Owesilisa noma owesifazane, futhi engokholwa – labo bayongena ePharadesi. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- Akazange athathe ingane, futhi akanaye umhlanganyeli ebukhosini. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- Futhi lowo u-Allah amholayo, nguyena oholwayo; futhi lowo amdukisayo, awuyikuthola. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- Bheka ukuthi bakunika kanjani izibonelo; badukile, futhi abakwazi ukuthola indlela. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- Yithi: "Ngempela, ngiyesaba, uma ngingalaleli iNkosi yami, isijeziso sosuku olukhulu." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- Izitho zazo eziyimfihlo zivezwa kuzo, futhi zaqala ukuzimboza ngamaqabunga asePharadesi. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- Futhi bizani labo eningakwazi, ngaphandle kuka-Allah, uma ningabaqiniso. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- Konke okusemhlabeni, nokunye okufana nakho, ukuze bazihlenge. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
